head.b:skin:
/* 
-----------------------------------------------
Blogger Template Style
Name:        Trendy Travel
Author :     way2themes.com
License:     Free Version
----------------------------------------------- */
/*****************************************
reset.css
******************************************/
html, body, .section, .widget, div, span, applet, object, iframe,
h1, h2, h3, h4, h5, h6, p, blockquote, pre,
a, abbr, acronym, address, big, cite, code,
del, dfn, em, font, img, ins, kbd, q, s, samp,
small, strike, strong, sub, sup, tt, var,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td, figure {    margin: 0;    padding: 0;}
html {   overflow-x: hidden;}
a {text-decoration:none;color:#000;}
article,aside,details,figcaption,figure,
footer,header,hgroup,menu,nav,section {     display:block;}
table {    border-collapse: separate;    border-spacing: 0;}
caption, th, td {    text-align: left;    font-weight: normal;}
blockquote:before, blockquote:after,
q:before, q:after {    content: "";}
.quickedit, .home-link{display:none;}
blockquote, q {    quotes: "" "";}
sup{    vertical-align: super;    font-size:smaller;}
code{    font-family: 'Lato', sans-serif;    font-size:12px;    color:#3E2723;}




a img{border:none;}
.widget img{max-width:100%;}
ol, ul { padding:0;  margin:0;  text-align: left;  }
ol li { list-style-type: decimal;  padding:0 0 5px;  }
ul li { list-style-type: disc;  padding: 0 0 5px;  }
ul ul, ol ol { padding: 0; }
#navbar-iframe, .navbar {   height:0px;   visibility:hidden;   display:none   }
#HTML300, #Text100, .post-footer-line.post-footer-line-1, .post-footer-line.post-footer-line-2 , .post-footer-line.post-footer-line-3 {
display: none;
}
.item-control {
display: none !important;
}
h2.date-header, h4.date-header {display:none;margin:1.5em 0 .5em}
h1, h2, h3, h4, h5, h6 {
font-family: 'Playfair Display', Georgia, serif;
color: #3E2723;
}
blockquote {
padding: 8px;
background-color: #fffaf4;
border-top: 1px solid #D8C3A5;
border-bottom: 1px solid #D8C3A5;
margin: 5px;
background-image: url(https://1.bp.blogspot.com/-siy6EKYCLtM/U6X4AdKrr0I/AAAAAAAANDs/HCjRvuedDro/s1600/openquote1.gif);
background-position: top left;
background-repeat: no-repeat;
text-indent: 23px;
}
blockquote p{
display: block;
background-image: url(https://3.bp.blogspot.com/-UjppXQI-ww0/U6X4IpheNiI/AAAAAAAAND0/PJhRvvhAWGU/s1600/closequote1.gif);
background-repeat: no-repeat;
background-position: bottom right;
}
/*****************************************
Custom css starts
******************************************/
body {
color: #3E2723;
font-family:'Lato', sans-serif;
font-size: 14px;
font-weight: normal;
line-height: 21px;
background: #fffaf4;
}
/* ######## Wrapper Css ######################### */
#outer-wrapper{max-width:100%;margin:0 auto;background-color:#fffaf4;box-shadow:0 0 5px RGBA(0, 0, 0, 0.2)}
.row{width:1170px}
#content-wrapper {
margin: 0 auto;
padding: 20px 0;
overflow: hidden;
}

#main-wrapper {
float: left;
width: 67%;
max-width: 800px;
}

#sidebar-wrapper {
float: right;
width: 30%;
max-width: 360px;
display:block;
}
/* ######## Top Header Bar Css ######################### */
.top-bar {
background: #222222;
}
.top-bar-wrapper {
position: relative;
min-height:40px;
color: #aaaaaa;
margin:0 auto;
}
.top-bar-social {
float: right;
padding: 5px 0;
}
.top-bar-social li {
display: inline;
padding: 0;
float: left;
margin-right: 5px;
;
}
.top-bar-social .widget ul {
padding: 0;
}
.top-bar-social .LinkList ul {
text-align: center;
margin: 0 20px 0 0;
}
.top-bar-social #social a {
display: block;
width: 30px;
height: 30px;
line-height: 30px;
font-size: 15px;
color: #aaaaaa;
transition: background 0.3s linear;
-moz-transition: background 0.3s linear;
-webkit-transition: background 0.3s linear;
-o-transition: background 0.3s linear;
}
.top-bar-social #social a:before {
display: inline-block;
font: normal normal normal 22px/1 FontAwesome;
font-size: inherit;
font-style: normal;
font-weight: 400;
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale;
}
.top-bar-social .bloglovin:before{content:"\f004"}
.top-bar-social .facebook:before{content:"\f09a"}
.top-bar-social .twitter:before{content:"\f099"}
.top-bar-social .gplus:before{content:"\f0d5"}
.top-bar-social .rss:before{content:"\f09e"}
.top-bar-social .youtube:before{content:"\f167"}
.top-bar-social .skype:before{content:"\f17e"}
.top-bar-social .stumbleupon:before{content:"\f1a4"}
.top-bar-social .tumblr:before{content:"\f173"}
.top-bar-social .vine:before{content:"\f1ca"}
.top-bar-social .stack-overflow:before{content:"\f16c"}
.top-bar-social .linkedin:before{content:"\f0e1"}
.top-bar-social .dribbble:before{content:"\f17d"}
.top-bar-social .soundcloud:before{content:"\f1be"}
.top-bar-social .behance:before{content:"\f1b4"}
.top-bar-social .digg:before{content:"\f1a6"}
.top-bar-social .instagram:before{content:"\f16d"}
.top-bar-social .pinterest:before{content:"\f0d2"}
.top-bar-social .delicious:before{content:"\f1a5"}
.top-bar-social .codepen:before{content:"\f1cb"}
.top-bar-social ul#social a:hover {
color: #fff;
opacity: 1;
}
.top-bar-menu {
float: left;
}
.top-menu ul {
overflow: hidden;
list-style: none;
padding: 0;
margin: 0;
}
.top-menu ul li {
float: left;
display: inline-block;
list-style: none;
padding: 0;
}
.top-menu ul li a {
padding: 10px 16px;
display: block;
border: none !important;
text-decoration: none;
line-height: inherit;
font-size: 14px;
font-weight: normal;
color: #aaaaaa;
}
.selectnav {display:none}
/* ######## Header Css ######################### */
.header-wrapper {
text-align: center;
padding: 42px 0;
background:#fffaf4
}
#header-inner {
text-align: center;
display: inline-block;
}
.header-wrapper img {
width:100%;
}
/* ######## Search widget Css ######################### */
#search-bar {
position: absolute;
right: 0;
top: 0;
}
.header-search {
color: #fff;
position: absolute;
top: 5px;
right: 0;
}
.header-search i {
font-style: normal;
font-size: 13px;
cursor: pointer;
}
.header-search .fa-times.active, .fa-search {
display: inline-block;
}
.header-search .fa-times,.fa-search.active {
display: none;
}
.search-form {
display: none;
position: absolute;
top: 35px;
right: 0;
padding: 5px;
background: #D8C3A5;
z-index: 9999;
transition: none;
}
.search-form input {
border: 1px solid #D8C3A5;
height: 36px;
text-indent: 5px;
}
.search-form button {
border: none;
border-radius: 3px;
color: #F8F1E7;
cursor: pointer;
font-size: 14px;
height: 36px;
width: 36px;
position: relative;
background: #ff6644;
}
.iconheader {
position: relative;
float: right;
}
.iconheader a i {
font-size: 18px;
line-height: 80px;
margin-left: 10px;
color: #999;
}
.iconheader a i:hover {
color:#E80007;
}
/* ######## Navigation Menu Css ######################### */
.navi-menu {
text-align: center;
margin: 0 auto;
padding: 0;
width: 100%;
background: #fffaf4;
    border-bottom: 1px solid rgba(0,0,0,.09);
}
.nav-menu {
margin: 0 auto;
border-top: 1px solid rgba(0,0,0,.09);
}
.selectnav {
display:none;
}
.nav-menu {
padding: 0;
}
.nav-menu ul {
list-style: none;
margin: 0;
padding: 0;
z-index: 999;
text-align: center;
}
.nav-menu ul li {
display: inline-block;
line-height: 1;
list-style: none outside none;
padding: 0;
text-align: left;
position: relative;
}
.nav-menu li a {
background: transparent;
color: #aaaaaa;
display: block;
font-size: 14px;
padding: 22px 20px;
position: relative;
text-decoration: none;
text-transform: uppercase;
font-weight: 700;
font-style: normal;
letter-spacing: 1px;
}
.nav-menu ul li:after {
    content: "|";
    display: block;
    position: absolute;
    margin: auto;
    top: -15px;
right: -5px;
    bottom: 0;
    width: 8px;
    height: 8px;
    text-align: center;
    font-weight: 400;
    font-size: 20px;
    text-rendering: auto;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    color: #dddddd;
}
.nav-menu ul li:last-child:after {
display: none;
}
.nav-menu li a i {
margin-right: 3px;
}
.nav-menu li a:hover, .nav-menu li a:hover .nav-menu ul li.hasSub a:after  {
background:#fffaf4;
color:#000;
}
.nav-menu ul li li a:hover {
padding-left: 20px;
}
.nav-menu ul li ul {
width: 180px;
margin: 0px;
position: absolute;
visibility: hidden;
display: inline;
padding: 0px;
height: auto;
border-top-width:0;
background: #fffaf4;
-webkit-box-shadow: 0 1px 0 1px rgba(0,0,0,.1);
box-shadow: 0 1px 0 1px rgba(0,0,0,.1);
}
.nav-menu ul li ul li ul {
left:180px;
top:0;
display:none;
}
.nav-menu ul li:hover ul {
visibility: visible;
}
.nav-menu ul li ul li:hover ul {
display:inline;
}
.nav-menu li li a {
color: #000000;
font-size: 14px;
padding: 15px 15px;
position: relative;
text-align: left;
-webkit-transition: color .15s linear 0s,padding-left .15s linear 0s;
}
.nav-menu li li {
float: none !important;
display: block;
position:relative;
}
.nav-menu a#pull {
display: none;
}
.nav-menu ul li.hasSub a {
padding-right: 25px
}
.nav-menu ul li.hasSub a:after {
color: #aaa;
position: absolute;
top: 22px;
right: 10px;
display: block;
content: "\f0d7";
font-family: FontAwesome;
font-weight: 400;
font-size: 15px;
text-rendering: auto;
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale
}
.nav-menu ul li.hasSub ul li a:after {
display: none!important
}
/* ######## Featured Widget Css ######################### */
.featured-slider-wrap {
    position: relative;
    padding: 15px;
    overflow: hidden;
    background: #fffaf4;
        border: 1px solid #D8C3A5;
    margin: 15px auto !important;
}
#label_with_thumbs .widget-thumb {
position: relative;
width: 100%;
height: 450px;
overflow: hidden;
display: block;
vertical-align: middle;
margin: 0!important;
}
#label_with_thumbs .widget-thumb .label_thumb {
position: relative;
height:100%;
width: 100%;
display: block;
}

#label_with_thumbs .widget-con {
position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    padding: 20px 10px;
    z-index: 2;
    box-sizing: border-box;
}
#label_with_thumbs .post-tag {
color: #fff;
text-transform: capitalize;
letter-spacing: 1px;
font-weight: 400;
font-style: normal;
    border: 1px solid #fff;
padding: 4px 8px;
margin-right: 8px;
border-radius: 2px;
font-size: 12px;
display: inline-block;
margin-bottom: 2px;
text-align: center;
}
#label_with_thumbs {
float: left;
width: 100%;
min-height: 70px;
margin:0;
padding: 0;
}

#label_with_thumbs li {
width: 100%;
float: left;
margin-left: 0;
border:none;
position:relative;
    margin-top: -15px;
    list-style-type: none;
}

#label_with_thumbs li .widget-sum {
display: none;
font-size: 16px;
line-height: 1.5em;
font-weight: 400;
margin: 7px 0 3px;
color: #fff;
text-align: justify;
}

#label_with_thumbs .recent-title {
overflow: hidden;
    font-weight: 700;
    font-size: 16px;
    line-height: 1.4em;
    margin: 5px 0 4px;
    padding: 0;
    letter-spacing: 1px;
}
#label_with_thumbs .recent-title a {
color: #fff;
transition: color .3s;
}
#label_with_thumbs li:nth-child(1) .widget-meta, #label_with_thumbs li:nth-child(1) .widget-meta a {
color:#F8F1E7;
}
.widget-meta {
color: #030303;
font-size: 11px;
font-weight: 400;
}
.img-overlay {
    position: absolute;
    left: 0;
    top: 0;
    z-index: 1;
    width: 100%;
    height: 100%;
    -webkit-box-shadow: 0 0 20px rgba(0,0,0,.8);
    box-shadow: 0 0 20px rgba(0,0,0,.8);
    background-color: #000;
    opacity: 0.3;
}
.owl-carousel .owl-wrapper:after {
content: ".";
display: block;
clear: both;
visibility: hidden;
line-height: 0;
height: 0;
}
.owl-carousel {
display: none;
position: relative;
width: 100%;
-ms-touch-action: pan-y;
}
.owl-carousel .owl-wrapper {
display: none;
position: relative;
-webkit-transform: translate3d(0px, 0px, 0px);
}
.owl-carousel .owl-wrapper-outer {
overflow: hidden;
position: relative;
width: 100%;
}
.owl-carousel .owl-wrapper-outer.autoHeight {
-webkit-transition: height 500ms ease-in-out;
-moz-transition: height 500ms ease-in-out;
-ms-transition: height 500ms ease-in-out;
-o-transition: height 500ms ease-in-out;
transition: height 500ms ease-in-out;
}
.owl-controls .owl-page,
.owl-controls .owl-buttons div {
cursor: pointer;
}
.owl-controls {
-webkit-user-select: none;
-khtml-user-select: none;
-moz-user-select: none;
-ms-user-select: none;
user-select: none;
-webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}
.grabbing,
.grabbing a,
.grabbing * {
cursor: e-resize!important;
}
.owl-carousel .owl-wrapper,
.owl-carousel .owl-item {
-webkit-backface-visibility: hidden;
-moz-backface-visibility: hidden;
-ms-backface-visibility: hidden;
-webkit-transform: translate3d(0, 0, 0);
-moz-transform: translate3d(0, 0, 0);
-ms-transform: translate3d(0, 0, 0);
}
.owl-prev,
.owl-next {
top: 40px;
color: #fff;
font-family: FontAwesome;
position: absolute;
z-index: 1;
display: block;
padding: 0;
cursor: pointer;
padding: 0;
text-align: center;
overflow: hidden;
width: 50px;
height: 50px;
line-height: 50px;
border: solid 2px #fff;
background:#D8C3A5;
opacity:0.7;
}
.label_with_thumbs .owl-prev,
.label_with_thumbs .owl-next {
margin-top: 0px;
font-size: 25px;
}
.label_with_thumbs .owl-prev {
left: 50px;
border-right: none;
}
.label_with_thumbs .owl-next {
right: 50px;
}
.label_with_thumbs .owl-dots {
bottom: 10px
}
.owl-next:before {
font-family: fontawesome;
}
.owl-prev:before {
font-family: fontawesome;
}
.owl-carousel {
padding: 5px 0;
}
.label_with_thumbs .owl-carousel {
border: 0;
padding: 0;
}
.label_with_thumbs .owl-item li {
margin: 0;
padding: 0;
}
.label_with_thumbs .owl-prev:hover,
.label_with_thumbs .owl-next:hover {
opacity: .9;
background:rgba(0, 0, 0, 0.5);
}
.owl-next:before {
content: '\f105';
font-family: fontawesome;
}
.owl-prev:before {
content: '\f104';
font-family: fontawesome;
}
.owl-carousel .owl-item {
float: left;
}
.box-title .owl-controls {
float: right;
}
.label_with_thumbs .owl-item li img {
height: auto;
width: 100%;
}
.label_with_thumbs .owl-item li .thumb-hover {
content: no-close-quote;
position: absolute;
bottom: -5px;
width: 100%;
background: url(https://2.bp.blogspot.com/-_IyTmlpHtg8/Vmi5pkn5ZAI/AAAAAAAACVI/G4Kylbm3CDo/s1600-r/gradient.png) repeat-x 0 -1px;
opacity: .8;
left: 0;
opacity: .9;
background-size: 200px 100%;
height: 200px;
}
/* ######## Sidebar Css ######################### */
.sidebar .widget {
margin-bottom: 20px;
position: relative;
}
.sidebar h2 {
background: #fffaf4;
color: #3E2723;
border: 1px solid #D8C3A5;
border-top: 3px solid #D8C3A5;
border-bottom-color: #D8C3A5;
font-size: 18px;
padding: 18px 30px;
letter-spacing: 1.5px;
text-transform: capitalize;
position: relative;
text-align: left;
}
.sidebar ul,.sidebar li{
list-style-type:none;
margin:0;
}
#sidebar .widget-content {
background: #fffaf4;
border: 1px solid #D8C3A5;
border-bottom: 2px solid #e8e8e8;
border-top: 0px;
    padding: 20px 15px;
}
/* ######## Post Css ######################### */
article {
    padding: 0;
}
.post-outer {
    padding: 0 0 20px 0;
}
.index .post, .archive .post {
text-align:center;
}
.post {
    display: block;
    overflow: hidden;
    word-wrap: break-word;
background: #fffaf4;
    border: 1px solid #efefef;
}
.post h2 {
margin-bottom: 12px;
line-height: 37px;
    font-size: 32px;
    font-weight: 700;
}
.post h2 a {
color: #000;
letter-spacing: 1px;
}
.post h2 {
    margin: 0 0 10px;
    padding: 0;
}


.retitle h2 {
    margin: 8px 0;
    display: block;
}
.post-body {
margin: 0px;
padding:10px;
font-size: 14px;
line-height: 26px;
width: auto;
word-wrap: break-word;
}
.block-image {
float: none;
margin: 0 auto;
clear: both;
width: 100%;
}
.block-image .thumb {
width: 100%;
height: 400px;
position: relative;
display: block;
overflow: hidden;
}
.block-image a {
width: 100%;
height: 400px;
display: block;
transition: all .3s ease-out!important;
-webkit-transition: all .3s ease-out!important;
-moz-transition: all .3s ease-out!important;
-o-transition: all .3s ease-out!important;
}
.date-header {
    color: #bdbdbd;
    display: block;
    font-size: 12px;
    font-weight: 400;
    line-height: 1.3em;
    margin: 0!important;
    padding: 0;
}
.date-header a {
    color: #bdbdbd;
}
.post-header {
    padding: 10px;
}
#meta-post {
float:right;
display:inline-block;
}
#meta-post .fa-calendar-o {
    margin-left: 8px;
}
.tag {
    display: inline-block;
    border-bottom: 2px solid #D8C3A5;
float:left;
}
.tag span.tag-icon {
background: #D8C3A5;
color: #fff;
display: inline-block;
    margin: 0 5px 0px 0;
position: relative;
padding: 2px 8px;
z-index: 1;
}
.tag span.tag-name {
      padding: 2px 6px 2px 0;
    font-size: 12px;
    font-family: 'Playfair Display', Georgia, serif;
    text-transform: uppercase;
    font-weight: bold;
    letter-spacing: 1px;
}
.post-meta {
    color: #bdbdbd;
    display: block;
    font-size: 13px;
    font-weight: 400;
    line-height: 21px;
    margin: 0;
    padding: 0;
}
.post-meta a, .post-meta i {
    color: #CBCBCB;
}
.post-timestamp {
    margin-left: 5px;
}
.label-head {
    margin-left: 5px;
}
.label-head a {
    padding-left: 2px;
}
.index-post-head {
    padding: 10px;
}
.resumo {
    margin-top: 10px;
    color: #8B6B4A;
    padding: 0 15px;
}
.resumo span {
    display: block;
    margin-bottom: 8px;
font-size: 18px;
    line-height: 25px;
    text-align: justify;
}
.resumo span:first-letter {
float: left;
    font-family: 'Playfair Display', Georgia, serif;
font-size: 40px;
line-height: 40px;
display: block;
text-align: center;
margin-right: 22px;
margin-top: 10px;
padding: 10px 14px;
margin-bottom: 10px;
border: 1px solid #D8C3A5;
color:#2b2b2b;
}
.post img {
max-width: 100%;
padding: 0;
position: relative;
margin:0 auto;
}
.post h3 {
font-size: 18px;
margin-top: 20px;
margin-bottom: 10px;
line-height: 1.1;
}
.second-meta {
  padding:10px 10px;
display: block;
overflow: hidden;  
}
.meta-top {
border-bottom: 1px dashed #D8C3A5;
border-top:none !important;
padding: 0 0 10px !important;
}
.meta-botom, .meta-top {
    display: block;
    overflow: hidden;
    border-bottom: 1px dashed #D8C3A5;
    padding: 10px 10px 0;
    margin-top: 10px;
}
.meta-botom .share-art {
position: relative;
}
.meta-botom .share-art span {
display: none;
}
.meta-botom .post-cmm {
float: left;
position: relative;
color: #000000;
background: #fffaf4;
padding: 0px;
height: 35px;
line-height: 32px;
text-transform: capitalize;
font-size: 12px;
letter-spacing: 1px;
}
.meta-botom .share-art {
float: right;
padding: 0;
padding-top: 0;
font-size: 13px;
font-weight: 400;
text-transform: capitalize;
}
.meta-botom .share-art a {
color: #fff;
padding: 5px 10px;
margin-left: 4px;
border-radius: 2px;
display: inline-block;
margin-right: 0;
}
