/* =========================================================
   SONIA — EDITORIAL BEIGE & WINE REDESIGN
   ========================================================= */
:root {
  --wine: #6B2C2C;
  --beige: #F8F1E7;
  --cream: #F8F1E7;
  --brown: #3E2723;
}
html, body {
  background: var(--cream) !important;
  color: var(--brown) !important;
  font-family: 'Lato', sans-serif !important;
}
body, p, li, input, button, textarea, select {
  font-family: 'Lato', sans-serif !important;
}
h1, h2, h3, h4, h5, h6,
.post-title, .sidebar h2, .read-more {
  font-family: 'Playfair Display', Georgia, serif !important;
  color: var(--wine);
}
a { color: var(--wine); }
a:hover { color: var(--brown); }

/* Main surfaces */
#outer-wrapper {
  background: var(--cream) !important;
  box-shadow: none !important;
}
.header-wrapper {
  background: var(--cream) !important;
  padding: 38px 0 !important;
}
#content-wrapper { padding-top: 28px !important; }
.post, .sidebar h2, #sidebar .widget-content, .comments,
.comments h4 {
  background: var(--cream) !important;
  border-color: #D8C3A5 !important;
}
.post { border: 1px solid #D8C3A5 !important; }
.post-body, .resumo, .post-meta, .date-header {
  color: var(--brown) !important;
}
.resumo span:first-letter {
  float: none !important;
  display: inline !important;
  font-family: inherit !important;
  font-size: inherit !important;
  line-height: inherit !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  color: inherit !important;
}

/* Header and both existing menus */
.top-bar {
  background: var(--beige) !important;
  border-bottom: 1px solid #E7D9C7;
}
.top-bar-wrapper { color: var(--brown) !important; }
.top-menu ul li a {
  color: var(--brown) !important;
  font-size: 12px !important;
  padding: 9px 13px !important;
  letter-spacing: .3px;
}
.top-menu ul li a:hover { color: var(--wine) !important; }
.top-bar-social #social a { color: var(--wine) !important; }
.navi-menu {
  background: var(--cream) !important;
  border-bottom: 1px solid #D8C3A5 !important;
}
.nav-menu { border-top: 1px solid #D8C3A5 !important; }
.nav-menu li a {
  color: var(--brown) !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  letter-spacing: 1.1px !important;
  padding: 17px 18px !important;
}
.nav-menu ul li:after { color: #D8C8B8 !important; }
.nav-menu li a:hover,
.nav-menu li a:hover .nav-menu ul li.hasSub a:after {
  background: transparent !important;
  color: var(--wine) !important;
}
.nav-menu ul li ul {
  background: var(--cream) !important;
  border: 1px solid #D8C3A5 !important;
  box-shadow: 0 8px 20px rgba(73,59,50,.08) !important;
}
.nav-menu li li a { color: var(--brown) !important; }

/* Post headings stay above their images on the home page */
.index-post-head { padding: 16px 20px 10px !important; }
.post h2, .post h2 a {
  color: var(--wine) !important;
  font-size: 27px !important;
  line-height: 1.25 !important;
  letter-spacing: 0 !important;
}
.post h2 a:hover { color: var(--brown) !important; }
.block-image .thumb, .block-image a {
  height: 350px !important;
}
.tag { border-bottom-color: var(--wine) !important; }
.tag span.tag-icon { background: var(--wine) !important; }
.tag span.tag-name, .tag span.tag-name a { color: var(--wine) !important; }
.post-meta a, .post-meta i, .date-header, .date-header a {
  color: #8A7569 !important;
}
.resumo { padding: 8px 20px 16px !important; }
.resumo span {
  font-size: 15px !important;
  line-height: 1.8 !important;
  text-align: left !important;
}
.read-more {
  background: var(--wine) !important;
  color: var(--cream) !important;
  font-family: 'Lato', sans-serif !important;
  font-size: 11px !important;
  letter-spacing: 1.2px;
  width: 150px !important;
  height: 42px !important;
  line-height: 42px !important;
  border-radius: 2px;
}
.read-more:hover { background: var(--brown) !important; }
.read-more:before, .read-more:after { border-color: var(--cream) !important; }

/* Category, label and archive pages: compact two-column editorial grid.
   The homepage remains a traditional full-width post list. */
#outer-wrapper.archive #main-wrapper,
body.index #outer-wrapper.index:not(.home) #main-wrapper {
  width: 67% !important;
  max-width: none !important;
}
#outer-wrapper.archive #main-wrapper .post-outer,
body.index #outer-wrapper.index:not(.home) #main-wrapper .post-outer {
  float: left !important;
  display: block !important;
  width: 50% !important;
  box-sizing: border-box !important;
  padding: 0 9px 18px !important;
}
#outer-wrapper.archive #main-wrapper .post,
body.index #outer-wrapper.index:not(.home) #main-wrapper .post {
  height: 100%;
  box-sizing: border-box;
}
#outer-wrapper.archive #main-wrapper .index-post-head,
body.index #outer-wrapper.index:not(.home) #main-wrapper .index-post-head {
  padding: 13px 13px 8px !important;
}
#outer-wrapper.archive #main-wrapper .post h2,
body.index #outer-wrapper.index:not(.home) #main-wrapper .post h2 {
  font-size: 18px !important;
  line-height: 1.3 !important;
}
#outer-wrapper.archive #main-wrapper .block-image .thumb,
#outer-wrapper.archive #main-wrapper .block-image a,
body.index #outer-wrapper.index:not(.home) #main-wrapper .block-image .thumb,
body.index #outer-wrapper.index:not(.home) #main-wrapper .block-image a {
  height: 215px !important;
}
#outer-wrapper.archive #main-wrapper .resumo,
body.index #outer-wrapper.index:not(.home) #main-wrapper .resumo {
  padding: 8px 13px 14px !important;
}
#outer-wrapper.archive #main-wrapper .resumo span,
body.index #outer-wrapper.index:not(.home) #main-wrapper .resumo span {
  font-size: 13px !important;
  line-height: 1.65 !important;
}
#outer-wrapper.archive #main-wrapper .second-meta,
body.index #outer-wrapper.index:not(.home) #main-wrapper .second-meta {
  padding: 8px 13px 13px !important;
}

/* Sidebar, labels, comments and pagination */
.sidebar h2, .comments h4 {
  color: var(--wine) !important;
  border-top: 3px solid var(--wine) !important;
  font-size: 18px !important;
  letter-spacing: .4px !important;
}
.sidebar .widget, #sidebar .widget-content { color: var(--brown) !important; }
.cloud-label-widget-content .label-size a {
  background: var(--beige) !important;
  color: var(--wine) !important;
  border: 1px solid #D8C3A5 !important;
}
.displaypageNum a, .showpage a, .pagecurrent,
.blog-pager-older-link, .blog-pager-newer-link {
  background: var(--beige) !important;
  color: var(--wine) !important;
  font-family: 'Lato', sans-serif !important;
}
.displaypageNum a:hover, .showpage a:hover, .pagecurrent,
.blog-pager-older-link:hover, .blog-pager-newer-link:hover {
  background: var(--wine) !important;
  color: var(--cream) !important;
}

/* Footer and remaining accent elements */
#jugas_footer {
  background-image: none !important;
  background-color: var(--brown) !important;
  color: var(--beige) !important;
}
.jugas_footer_copyright a { color: var(--beige) !important; }
.sub-wrap {
  background: var(--wine) !important;
  border-top-color: rgba(73,59,50,.25) !important;
}
.subscribe-css-email-button {
  background: var(--beige) !important;
  color: var(--wine) !important;
}
.search-form { background: var(--beige) !important; }
.search-form button { background: var(--wine) !important; }
.comments .comments-content .icon.blog-author:after {
  background: var(--wine) !important;
}

/* Responsive layout */
@media only screen and (max-width: 768px) {
  #outer-wrapper.archive #main-wrapper,
  body.index #outer-wrapper.index:not(.home) #main-wrapper {
    width: 100% !important;
  }
  #outer-wrapper.archive #main-wrapper .post-outer,
  body.index #outer-wrapper.index:not(.home) #main-wrapper .post-outer {
    width: 50% !important;
    padding: 0 6px 12px !important;
  }
  #outer-wrapper.archive #main-wrapper .block-image .thumb,
  #outer-wrapper.archive #main-wrapper .block-image a,
  body.index #outer-wrapper.index:not(.home) #main-wrapper .block-image .thumb,
  body.index #outer-wrapper.index:not(.home) #main-wrapper .block-image a {
    height: 175px !important;
  }
}
@media only screen and (max-width: 480px) {
  #outer-wrapper.archive #main-wrapper .post-outer,
  body.index #outer-wrapper.index:not(.home) #main-wrapper .post-outer {
    width: 100% !important;
    padding: 0 0 14px !important;
  }
  .block-image .thumb, .block-image a { height: 260px !important; }
  .post h2, .post h2 a { font-size: 23px !important; }
}



/* ===== Refinamento visual: categorias, menu e marcadores ===== */
#Label1 {
  margin: 22px 0 28px !important;
}
#Label1 h2 {
  color: #6B2C2C !important;
  background: #fffaf4 !important;
  border: 0 !important;
  border-bottom: 2px solid #6B2C2C !important;
  padding: 12px 4px 14px !important;
  margin: 0 0 16px !important;
  font-family: 'Playfair Display', Georgia, serif !important;
  font-size: 23px !important;
  font-weight: 600 !important;
  letter-spacing: .3px !important;
  text-align: left !important;
}
#Label1 .cloud-label-widget-content {
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(125px, 1fr)) !important;
  gap: 10px !important;
  width: 100% !important;
}
#Label1 .cloud-label-widget-content .label-size {
  display: block !important;
  float: none !important;
  margin: 0 !important;
  min-width: 0 !important;
  text-align: center !important;
}
#Label1 .cloud-label-widget-content .label-size a,
#Label1 .cloud-label-widget-content .label-size > span {
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-height: 42px !important;
  width: 100% !important;
  padding: 10px 12px !important;
  background: #fffaf4 !important;
  color: #6B2C2C !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 8px !important;
  font-family: 'Lato', sans-serif !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  line-height: 1.3 !important;
  text-transform: capitalize !important;
  transition: background .2s ease, color .2s ease, border-color .2s ease, transform .2s ease !important;
}
#Label1 .cloud-label-widget-content .label-size a:hover {
  background: #6B2C2C !important;
  color: #fff !important;
  border-color: #6B2C2C !important;
  transform: translateY(-2px);
}
.navi-menu {
  background: #fffaf4 !important;
  border-bottom: 1px solid #D8C3A5 !important;
}
.nav-menu {
  border-top: 0 !important;
}
.nav-menu ul li:after {
  content: none !important;
  display: none !important;
}
.nav-menu li a {
  color: #6B2C2C !important;
  padding: 18px 22px !important;
  font-family: 'Lato', sans-serif !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  letter-spacing: 1.1px !important;
  border-radius: 0 !important;
  transition: background .2s ease, color .2s ease !important;
}
.nav-menu li a:hover {
  background: #6B2C2C !important;
  color: #fff !important;
}
.nav-menu ul li ul {
  background: #fffaf4 !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 6px !important;
  box-shadow: 0 8px 22px rgba(81,75,75,.12) !important;
  overflow: hidden;
}
.nav-menu li li a {
  color: #3E2723 !important;
  padding: 13px 16px !important;
  border-radius: 0 !important;
}
.nav-menu li li a:hover {
  background: #fffaf4 !important;
  color: #6B2C2C !important;
}

/* Marcadores das postagens em grade */
.post .post-footer-line.post-footer-line-2 {
  display: block !important;
  padding: 12px 14px 16px !important;
  border-top: 1px solid #F0E8DE !important;
}
.post .post-footer-line-2 .post-labels {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  gap: 8px !important;
  color: #6B2C2C !important;
  font-size: 0 !important;
}
.post .post-footer-line-2 .post-labels a {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  padding: 6px 11px !important;
  background: #fffaf4 !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 6px !important;
  color: #6B2C2C !important;
  font-family: 'Lato', sans-serif !important;
  font-size: 12px !important;
  line-height: 1.3 !important;
  text-decoration: none !important;
  transition: all .2s ease !important;
}
.post .post-footer-line-2 .post-labels a:hover {
  background: #6B2C2C !important;
  border-color: #6B2C2C !important;
  color: #fff !important;
}
@media (max-width: 600px) {
  #Label1 .cloud-label-widget-content {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
  .nav-menu li a {
    padding: 14px 12px !important;
    font-size: 11px !important;
  }
}



/* ===== Menu superior refinado e remoção dos tons marrons ===== */
.top-bar {
  background: #6B2C2C !important;
  border: 0 !important;
  box-shadow: 0 3px 12px rgba(76, 25, 40, .12) !important;
}
.top-bar-wrapper {
  min-height: 46px !important;
  color: #F8F1E7 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}
.top-bar-menu, .top-menu {
  float: none !important;
}
.top-menu ul {
  display: flex !important;
  align-items: center !important;
  gap: 7px !important;
}
.top-menu ul li {
  float: none !important;
  display: block !important;
}
.top-menu ul li a {
  display: inline-flex !important;
  align-items: center !important;
  min-height: 34px !important;
  padding: 7px 14px !important;
  color: #F8F1E7 !important;
  background: transparent !important;
  border: 1px solid transparent !important;
  border-radius: 20px !important;
  font-family: 'Lato', sans-serif !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  letter-spacing: 1px !important;
  line-height: 1 !important;
  text-transform: uppercase !important;
  transition: all .2s ease !important;
}
.top-menu ul li a:hover {
  color: #6B2C2C !important;
  background: #fffaf4 !important;
  border-color: #F8F1E7 !important;
}
.top-bar-social #social a {
  color: #F8F1E7 !important;
  opacity: .9 !important;
}
.top-bar-social #social a:hover {
  color: #D8C3A5 !important;
  opacity: 1 !important;
}

/* Neutralize brown text accents while preserving the wine palette */
html, body {
  color: #3E2723 !important;
}
.post-body, .resumo, .post-meta, .date-header,
.top-bar-wrapper, .top-menu ul li a {
  color: #3E2723;
}
a:hover { color: #6B2C2C !important; }
.nav-menu li li a { color: #3E2723 !important; }

@media (max-width: 768px) {
  .top-bar-wrapper {
    display: block !important;
    text-align: center !important;
    padding: 5px 0 !important;
  }
  .top-menu ul {
    justify-content: center !important;
    flex-wrap: wrap !important;
    gap: 3px !important;
  }
  .top-menu ul li a {
    padding: 7px 10px !important;
    font-size: 10px !important;
  }
  .top-bar-social {
    text-align: center !important;
    margin-top: 3px !important;
  }
}


/* ===== Ajuste final do segundo menu: hierarquia real dos submenus ===== */
.navi-menu { overflow: visible !important; position: relative !important; z-index: 1000 !important; }
.nav-menu, .nav-menu .widget, .nav-menu .widget-content { overflow: visible !important; }
.nav-menu > .widget-content > ul,
.nav-menu .widget-content > ul {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 2px 8px !important;
}
.nav-menu ul li { position: relative !important; }
.nav-menu ul li:after { display: none !important; content: none !important; }
.nav-menu > .widget-content > ul > li > a,
.nav-menu .widget-content > ul > li > a {
  white-space: nowrap !important;
}
.nav-menu ul li ul {
  display: none !important;
  position: absolute !important;
  top: 100% !important;
  left: 0 !important;
  min-width: 205px !important;
  width: max-content !important;
  max-width: 260px !important;
  padding: 7px !important;
  margin: 0 !important;
  background: #fffaf4 !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 8px !important;
  box-shadow: 0 10px 24px rgba(60, 35, 40, .13) !important;
  z-index: 99999 !important;
  text-align: left !important;
}
.nav-menu ul li:hover > ul,
.nav-menu ul li:focus-within > ul { display: block !important; visibility: visible !important; }
.nav-menu ul li ul li { display: block !important; width: 100% !important; }
.nav-menu ul li ul li a {
  display: block !important;
  width: 100% !important;
  box-sizing: border-box !important;
  padding: 11px 13px !important;
  color: #3E2723 !important;
  white-space: normal !important;
  text-transform: none !important;
  letter-spacing: .2px !important;
  border-radius: 0 !important;
}
.nav-menu ul li ul li a:hover {
  background: #fffaf4 !important;
  color: #6B2C2C !important;
}
.nav-menu ul li ul li ul {
  top: 0 !important;
  left: 100% !important;
}
@media (max-width: 880px) {
  .nav-menu .widget-content > ul { display: none !important; }
  .nav-menu .menu-mobile-select {
    display: block !important;
    width: min(92%, 320px) !important;
    margin: 10px auto !important;
    padding: 10px 12px !important;
    border: 1px solid #D8C3A5 !important;
    border-radius: 7px !important;
    background: #fffaf4 !important;
    color: #6B2C2C !important;
    font: 600 13px 'Lato', sans-serif !important;
  }
}

/* ===== Categorias em nuvem de etiquetas ===== */
#Label1 { margin: 24px 0 30px !important; }
#Label1 h2 {
  margin: 0 0 15px !important;
  padding: 0 0 11px !important;
  background: transparent !important;
  border: 0 !important;
  border-bottom: 1px solid #D8C3A5 !important;
  color: #6B2C2C !important;
  font: 600 22px 'Playfair Display', Georgia, serif !important;
  letter-spacing: .2px !important;
  text-align: left !important;
}
#Label1 .cloud-label-widget-content {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 9px 10px !important;
  width: 100% !important;
  padding: 3px 0 !important;
  text-align: left !important;
}
#Label1 .cloud-label-widget-content .label-size {
  display: inline-flex !important;
