  width: auto !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1.2 !important;
  opacity: 1 !important;
}
#Label1 .cloud-label-widget-content .label-size a,
#Label1 .cloud-label-widget-content .label-size > span {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: auto !important;
  min-height: 0 !important;
  box-sizing: border-box !important;
  padding: 8px 13px !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 999px !important;
  background: #fffaf4 !important;
  color: #6B2C2C !important;
  font: 500 12px/1.25 'Lato', sans-serif !important;
  letter-spacing: .15px !important;
  text-transform: none !important;
  transition: background .2s ease, color .2s ease, transform .2s ease !important;
}
#Label1 .cloud-label-widget-content .label-size-1 a,
#Label1 .cloud-label-widget-content .label-size-1 > span { font-size: 11px !important; }
#Label1 .cloud-label-widget-content .label-size-2 a,
#Label1 .cloud-label-widget-content .label-size-2 > span { font-size: 12px !important; }
#Label1 .cloud-label-widget-content .label-size-3 a,
#Label1 .cloud-label-widget-content .label-size-3 > span { font-size: 13px !important; }
#Label1 .cloud-label-widget-content .label-size-4 a,
#Label1 .cloud-label-widget-content .label-size-4 > span { font-size: 14px !important; }
#Label1 .cloud-label-widget-content .label-size-5 a,
#Label1 .cloud-label-widget-content .label-size-5 > span { font-size: 15px !important; }
#Label1 .cloud-label-widget-content .label-size-6 a,
#Label1 .cloud-label-widget-content .label-size-6 > span { font-size: 16px !important; }
#Label1 .cloud-label-widget-content .label-size a:hover {
  background: #6B2C2C !important;
  border-color: #6B2C2C !important;
  color: #F8F1E7 !important;
  transform: translateY(-2px) !important;
}
@media (max-width: 600px) {
  #Label1 .cloud-label-widget-content { gap: 8px !important; }
  #Label1 .cloud-label-widget-content .label-size a,
  #Label1 .cloud-label-widget-content .label-size > span { padding: 7px 11px !important; }
}

/* Ajuste visual: categorias com tipografia uniforme e cantos discretos */
#Label1 .cloud-label-widget-content .label-size a,
#Label1 .cloud-label-widget-content .label-size > span,
#Label1 .cloud-label-widget-content .label-size-1 a,
#Label1 .cloud-label-widget-content .label-size-1 > span,
#Label1 .cloud-label-widget-content .label-size-2 a,
#Label1 .cloud-label-widget-content .label-size-2 > span,
#Label1 .cloud-label-widget-content .label-size-3 a,
#Label1 .cloud-label-widget-content .label-size-3 > span,
#Label1 .cloud-label-widget-content .label-size-4 a,
#Label1 .cloud-label-widget-content .label-size-4 > span,
#Label1 .cloud-label-widget-content .label-size-5 a,
#Label1 .cloud-label-widget-content .label-size-5 > span,
#Label1 .cloud-label-widget-content .label-size-6 a,
#Label1 .cloud-label-widget-content .label-size-6 > span {
  font-family: 'Lato', sans-serif !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  font-style: normal !important;
  line-height: 1.35 !important;
  letter-spacing: 0 !important;
  padding: 7px 11px !important;
  border: 1px solid #D8C3A5 !important;
  border-bottom: 2px solid #D8C4AD !important;
  border-radius: 3px !important;
  background: #FBF7F0 !important;
  color: #6B2C2C !important;
  text-decoration: none !important;
  transform: none !important;
}
#Label1 .cloud-label-widget-content .label-size a:hover {
  background: #6B2C2C !important;
  border-color: #6B2C2C !important;
  color: #F8F1E7 !important;
  transform: translateY(-1px) !important;
}
@media (max-width: 600px) {
  #Label1 .cloud-label-widget-content { gap: 7px 8px !important; }
  #Label1 .cloud-label-widget-content .label-size a,
  #Label1 .cloud-label-widget-content .label-size > span { padding: 6px 9px !important; }
}



/* ===== Ajustes finais aprovados: etiquetas da lateral e caixa do post ===== */
#Label1 {
  margin: 22px 0 30px !important;
}
#Label1 h2 {
  color: #6B2C2C !important;
  background: transparent !important;
  border: 0 !important;
  border-bottom: 1px solid #E7D6C5 !important;
  padding: 0 0 13px !important;
  margin: 0 0 15px !important;
  font-family: 'Playfair Display', Georgia, serif !important;
  font-size: 22px !important;
  font-weight: 600 !important;
  letter-spacing: .2px !important;
  text-align: left !important;
}
#Label1 .cloud-label-widget-content {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 9px 10px !important;
  width: 100% !important;
  padding: 2px 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}
#Label1 .cloud-label-widget-content .label-size {
  display: inline-flex !important;
  float: none !important;
  width: auto !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1.3 !important;
}
#Label1 .cloud-label-widget-content .label-size a,
#Label1 .cloud-label-widget-content .label-size > span {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  width: auto !important;
  min-height: 36px !important;
  margin: 0 !important;
  padding: 8px 13px !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 7px !important;
  background: #fffaf4 !important;
  box-shadow: 0 1px 0 rgba(118, 44, 61, .05) !important;
  color: #6B2C2C !important;
  font-family: 'Lato', sans-serif !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  line-height: 1.35 !important;
  letter-spacing: 0 !important;
  text-decoration: none !important;
  text-transform: none !important;
  white-space: normal !important;
  transition: background .2s ease, border-color .2s ease, color .2s ease !important;
}
#Label1 .cloud-label-widget-content .label-size a:hover {
  background: #6B2C2C !important;
  border-color: #6B2C2C !important;
  color: #F8F1E7 !important;
}

/* Caixa de conteúdo das postagens: creme, moldura fina e topo vinho */
.post .post-body {
  position: relative !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
  margin: 24px 0 !important;
  padding: 38px 34px 32px !important;
  background: #fffaf4 !important;
  border: 1px solid #D8C3A5 !important;
  border-radius: 18px !important;
  box-shadow: 0 8px 24px rgba(91, 52, 43, .055) !important;
}
.post .post-body:before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: 10px !important;
  background: #6B2C2C !important;
  border-radius: 17px 17px 0 0 !important;
  pointer-events: none !important;
}
@media (max-width: 600px) {
  #Label1 .cloud-label-widget-content { gap: 8px !important; }
  #Label1 .cloud-label-widget-content .label-size a,
  #Label1 .cloud-label-widget-content .label-size > span {
    min-height: 34px !important;
    padding: 7px 11px !important;
    font-size: 12px !important;
  }
  .post .post-body {
    margin: 18px 0 !important;
    padding: 30px 19px 22px !important;
    border-radius: 15px !important;
  }
  .post .post-body:before { border-radius: 14px 14px 0 0 !important; }
}



/* ===== Uniformizar o conteúdo da postagem e o rodapé ===== */
.post .post-body {
  background: #fffaf4 !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 24px 0 !important;
  padding: 28px 34px 32px !important;
}
.post .post-body:before {
  display: none !important;
  content: none !important;
}
@media (max-width: 600px) {
  .post .post-body {
    background: #fffaf4 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 22px 19px 24px !important;
  }
}

/* Rodapé com o mesmo fundo da página, sem marrom ou imagem */
#jugas_footer {
  background: #fffaf4 !important;
  background-image: none !important;
  color: #3E2723 !important;
  border-top: 1px solid #D8C3A5 !important;
}
#jugas_footer .jugas_footer_copyright,
#jugas_footer .jugas_footer_copyright a,
#jugas_footer .foot-social,
#jugas_footer #social a {
  color: #3E2723 !important;
}
#jugas_footer .jugas_footer_copyright a:hover,
#jugas_footer #social a:hover {
  color: #6B2C2C !important;
}

/* Oculta a caixa genérica "About" do template e o perfil automático */
.sora-author-box,
.author-profile {
  display: none !important;
}


/* ===== Ajuste estrutural do conteúdo e sidebar ===== */
#content-wrapper.row {
  display: flex !important;
  align-items: flex-start !important;
  justify-content: space-between !important;
  gap: 3% !important;
  width: 96% !important;
  max-width: 1170px !important;
  margin: 0 auto !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  box-sizing: border-box !important;
  overflow: visible !important;
}
#content-wrapper > #main-wrapper {
  float: none !important;
  clear: none !important;
  flex: 0 0 67% !important;
  width: 67% !important;
  max-width: none !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
}
#content-wrapper > #sidebar-wrapper {
  float: none !important;
  clear: none !important;
  flex: 0 0 30% !important;
  width: 30% !important;
  max-width: 360px !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding-top: 0 !important;
  box-sizing: border-box !important;
}
#content-wrapper > #sidebar-wrapper .widget,
#content-wrapper > #sidebar-wrapper .widget-content {
  max-width: 100%;
  box-sizing: border-box;
}
@media only screen and (max-width: 600px) {
  #content-wrapper.row {
    display: block !important;
    width: 94% !important;
  }
  #content-wrapper > #main-wrapper,
  #content-wrapper > #sidebar-wrapper {
    display: block !important;
    float: none !important;
    clear: both !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 auto !important;
  }
  #content-wrapper > #sidebar-wrapper {
    padding-top: 24px !important;
  }
}



/* Páginas de marcadores: ocultar a faixa de status */
.status-msg-wrap {
  display: none !important;
}




/* Oculta somente a linha inferior dos cards nas listas de posts.
   A categoria do topo (.tag) continua visivel. */
body.index .post .post-footer-line.post-footer-line-2,
body.archive .post .post-footer-line.post-footer-line-2,
#outer-wrapper.index .post .post-footer-line.post-footer-line-2,
#outer-wrapper.archive .post .post-footer-line.post-footer-line-2 {
  display: none !important;
}



/* ===== Vintage Soul — paleta e correções ===== */
:root{--cream:#F8F1E7;--beige:#D8C3A5;--coffee:#8B6B4A;--burgundy:#6B2C2C;--choco:#3E2723;}
::selection{background:var(--burgundy);color:var(--cream);}
body{background:var(--cream)!important;color:var(--choco);font-family:'Lato',sans-serif;font-size:15px;line-height:1.7;}
h1,h2,h3,h4,h5,h6,.post-title,.post-title a,.widget h2,.title{font-family:'Playfair Display',Georgia,serif;color:var(--choco);letter-spacing:.01em;}
a{color:var(--choco);transition:color .25s ease;} a:hover{color:var(--burgundy);}
.post-body a{color:var(--burgundy);text-decoration:underline;text-underline-offset:3px;}
blockquote{background:#fffaf4;border:0;border-left:4px solid var(--burgundy);border-radius:0 12px 12px 0;padding:18px 22px;margin:20px 0;font-family:'Playfair Display',serif;font-style:italic;color:var(--choco);background-image:none;text-indent:0;}
blockquote p{background-image:none;}
img{max-width:100%;height:auto;}
.post-body img{border-radius:14px;}
input,textarea,select{border:1px solid var(--beige)!important;border-radius:10px;background:#fffaf4;color:var(--choco);font-family:'Lato',sans-serif;}
input:focus,textarea:focus{outline:2px solid var(--coffee);outline-offset:1px;}
button,input[type=submit],.btn,.read-more,a.more-link{background:var(--burgundy)!important;color:var(--cream)!important;border:0!important;border-radius:999px;transition:background .25s ease;}
button:hover,input[type=submit]:hover,.read-more:hover,a.more-link:hover{background:var(--choco)!important;}
.sidebar .widget,.widget-content{border-color:var(--beige);}
.post-labels a,.label-size a,.Label a{background:var(--beige);color:var(--choco);border-radius:999px;padding:3px 12px;}
.post-labels a:hover,.Label a:hover{background:var(--burgundy);color:var(--cream);}
#footer,.footer,footer{background:var(--choco);color:var(--beige);}
#footer a,footer a{color:var(--cream);} #footer a:hover,footer a:hover{color:var(--beige);}
.blog-pager a,#blog-pager a{background:var(--beige);color:var(--choco);border-radius:999px;padding:8px 18px;}
.blog-pager a:hover,#blog-pager a:hover{background:var(--burgundy);color:var(--cream);}
@media(max-width:768px){body{font-size:15px;} .post-body img{border-radius:10px;}}

/* ===== Ajustes v2 ===== */
.post-title,.post-title a,h1.post-title,h2.post-title,.post-head h1.post-title{font-size:27px!important;line-height:1.25!important;margin-bottom:8px!important;}
@media(max-width:768px){.post-title,.post-title a,h1.post-title,h2.post-title{font-size:23px!important;}}
.post-body img,.post-thumb,.post-image,.thumb,.post-header img{margin-bottom:0!important;display:block;}
.post-body .separator,.post-body .separator a{margin-bottom:12px!important;padding-bottom:0!important;}
.post-body .tr-caption-container{margin-bottom:12px!important;} .post-body .tr-caption{padding-top:6px!important;}
.post-header,.post-head,.post-thumb,.post-image-wrap{margin-bottom:14px!important;padding-bottom:0!important;}
.post-meta,.post-header,.post-header-line-1,.date-header,.second-meta{text-align:left!important;justify-content:flex-start!important;}
.post-meta{display:flex;flex-wrap:wrap;align-items:center;gap:6px 16px;margin:6px 0 14px!important;font-size:13px;color:var(--coffee);}
.post-meta .post-author,.post-meta .post-timestamp{float:none!important;margin:0!important;}
.share-box{display:flex;flex-wrap:wrap;align-items:center;gap:12px;border-top:1px solid var(--beige);padding-top:16px;margin-top:20px;}
.share-title,.footer-meta .share-title{font-family:'Playfair Display',serif;font-size:17px;color:var(--choco);background:none!important;padding:0!important;margin:0!important;}
.share-title:after,.footer-meta .share-title:after{display:none!important;}
.share-art{display:flex!important;flex-wrap:wrap;gap:8px;float:none!important;}
.share-art a,.footer-meta .share-art a,.meta-botom .share-art a,.second-meta .share-art a{display:inline-flex!important;align-items:center;gap:6px;height:36px;padding:0 14px!important;border-radius:999px!important;background:transparent!important;border:1px solid var(--beige)!important;color:var(--choco)!important;font-size:13px;width:auto!important;line-height:1!important;transition:all .2s ease;}
.share-art a:hover,.footer-meta .share-art a:hover{background:var(--burgundy)!important;border-color:var(--burgundy)!important;color:var(--cream)!important;}
.share-art a svg{flex-shrink:0;}
.share-art a i{display:none!important;}
@media(max-width:600px){.share-art span{display:none!important;} .share-art a{width:36px!important;padding:0!important;justify-content:center;}}

/* ===== Ajustes v3: sem cantos arredondados ===== */
.share-art a,.footer-meta .share-art a,.meta-botom .share-art a,.second-meta .share-art a,
button,input[type=submit],.btn,.read-more,a.more-link,.blog-pager a,#blog-pager a,
.post-labels a,.label-size a,.Label a{border-radius:0!important;}
#related-posts{display:block!important;}
#related-posts .related-card{border-radius:0!important;}

/* ===== Ajustes v4 ===== */
/* Títulos menores */
.index .post h2,.archive .post h2,.index .post h2 a,.archive .post h2 a,
.index .post-title,.archive .post-title,.index .post-title a,.archive .post-title a{font-size:21px!important;line-height:1.3!important;margin:6px 0 10px!important;}
body .post-head h1.post-title,.item h1.post-title,.static_page h1.post-title{font-size:26px!important;line-height:1.25!important;margin:0 0 6px!important;}
@media(max-width:768px){.index .post h2,.archive .post h2,.index .post h2 a,.archive .post h2 a{font-size:19px!important;} .item h1.post-title{font-size:23px!important;}}
/* Espaços vazios dentro da postagem */
.item .post-body>br:first-child,.item .post-body>div:first-child>br:first-child{display:none;}
.item .post-body .separator:first-child,.item .post-body>div:first-child .separator:first-child{margin-top:0!important;}
.item .post-body{padding-top:4px!important;margin-top:0!important;}
.item .post-body>br+br,.item .post-body>div>br+br{display:none;}
.item .post-body::after{content:"";display:table;clear:both;}
.footer-meta{margin-top:10px!important;padding-top:0!important;}
.share-box{margin-top:14px!important;padding-top:14px!important;}
/* Compartilhar: ícones pequenos e discretos */
.share-art a,.footer-meta .share-art a,.meta-botom .share-art a,.second-meta .share-art a{height:30px!important;padding:0 10px!important;font-size:12px!important;gap:5px!important;margin:0!important;border:1px solid var(--beige)!important;background:transparent!important;}
.share-art a svg{width:13px;height:13px;}
.meta-botom{display:flex!important;align-items:center;justify-content:space-between;gap:10px;padding:10px 0!important;}
.meta-botom .post-cmm{float:none!important;background:transparent!important;color:var(--coffee)!important;height:auto!important;line-height:1!important;font-size:12px!important;}
.meta-botom .share-art{float:none!important;gap:4px!important;}
.meta-botom .share-art a{width:28px!important;height:28px!important;padding:0!important;justify-content:center;border:0!important;color:var(--coffee)!important;}
.meta-botom .share-art a:hover{color:var(--burgundy)!important;background:transparent!important;}
.meta-botom .share-art a svg{width:14px;height:14px;}
.meta-botom .share-art span{display:none!important;}
/* Mensagem do marcador */
.status-msg-wrap{width:auto!important;margin:0 0 20px!important;font-size:14px;}
.status-msg-border,.status-msg-bg{display:none!important;}
.status-msg-body{position:static!important;padding:12px 16px!important;background:transparent!important;border-left:3px solid var(--burgundy)!important;color:var(--choco);text-align:left!important;font-family:'Lato',sans-serif;}
.status-msg-body a{color:var(--burgundy)!important;text-decoration:underline;}
.status-msg-hidden{display:inline!important;visibility:visible!important;}
/* Postagens relacionadas */
#related-posts{margin:24px 0 8px!important;padding:20px 0 0!important;border-top:1px solid var(--beige)!important;overflow:visible!important;}
#related-posts .related-heading{display:block!important;font-family:'Playfair Display',Georgia,serif!important;font-size:20px!important;color:var(--choco)!important;margin:0 0 14px!important;text-align:left!important;font-weight:600;}
#related-posts .related-heading:before,#related-posts .related-heading:after{display:none!important;}
#related-posts .related-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:14px!important;}
#related-posts .related-card{display:block!important;background:transparent!important;border:0!important;border-radius:0!important;text-decoration:none!important;box-shadow:none!important;transform:none!important;}
#related-posts .related-card img{display:block!important;width:100%!important;height:auto!important;aspect-ratio:4/3;object-fit:cover!important;margin:0 0 8px!important;border-radius:0!important;transition:opacity .2s;}
#related-posts .related-card:hover img{opacity:.85;}
#related-posts .related-card-title{display:block!important;padding:0!important;font-family:'Playfair Display',Georgia,serif!important;font-size:15px!important;line-height:1.35!important;color:var(--choco)!important;}
#related-posts .related-card:hover .related-card-title{color:var(--burgundy)!important;}
@media(max-width:600px){#related-posts .related-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important;} #related-posts .related-card-title{font-size:14px!important;}}

/* ===== Ajustes v5: fotos retas e espaçamento uniforme ===== */
img,.post-body img,.post-thumb,.post-thumb img,.post-image img,.snippets img,.index .post img,.archive .post img,.related-card img,.sora-author-box img{border-radius:0!important;}
.post-body .separator,.post-body .separator a{display:block!important;margin:16px 0!important;padding:0!important;text-align:center!important;float:none!important;}
.post-body .separator a{margin:0!important;}
.post-body img{display:block!important;margin:0 auto!important;max-width:100%!important;height:auto!important;padding:0!important;}
.post-body>img,.post-body>a>img{margin:16px auto!important;}
.post-body .separator:first-child,.post-body>div:first-child .separator:first-child,.post-body>img:first-child{margin-top:4px!important;}
.index .post .post-thumb,.archive .post .post-thumb,.index .post-image-wrap,.archive .post-image-wrap{margin:0!important;padding:0!important;}
.index .post img,.archive .post img{display:block;width:100%!important;margin:0!important;}

/* ===== Ajustes v6: títulos um pouco maiores ===== */
.index .post h2,.archive .post h2,.index .post h2 a,.archive .post h2 a,
.index .post-title,.archive .post-title,.index .post-title a,.archive .post-title a{font-size:24px!important;}
body .post-head h1.post-title,.item h1.post-title,.static_page h1.post-title{font-size:30px!important;}
@media(max-width:768px){.index .post h2,.archive .post h2,.index .post h2 a,.archive .post h2 a{font-size:21px!important;} body .item h1.post-title{font-size:25px!important;}}

/* ===== dailysoh: fundo bege aplicado também ao interior das postagens ===== */
html, body, body#layout {
  background-color: #FFFAF4 !important;
}
body #outer-wrapper,
body #content-wrapper,
body #main-wrapper,
body #main,
body .main,
body .main-inner,
body .blog-posts,
body .date-outer,
body .date-posts,
body .post-outer,
body article,
body article.post,
body .post,
body .post-inner,
body .post-content,
body .post-body,
body .post-body-container,
body .post-footer,
body .post-footer-line,
body .post-bottom,
body .post-header,
body .post-title,
body.item .blog-posts,
body.item .date-outer,
body.item .date-posts,
body.item .post-outer,
body.item article,
body.item .post,
body.item .post-body,
body.item .post-content {
  background-color: #fffaf4 !important;
  background-image: none !important;
}
body .post,
body article.post,
body.item .post-outer,
body.item .post {
  border-color: #D8C3A5 !important;
}
body .post-body,
body.item .post-body {
  color: #3E2723 !important;
  padding: 18px !important;
}
body .post-body p,
body .post-body div,
body .post-body span,
body .post-body li,
body .post-body blockquote {
  color: #3E2723;
}
body .post-body a { color: #6B2C2C !important; }

/* Fundo claro unificado */
html:not(#_x#_x#_x),body:not(#_x#_x#_x),body *:not(a):not(button):not(input[type=submit]):not(input[type=Submit]):not(input[type=button]):not(.search-form):not(iframe):not(img):not(.tag-icon):not(.pagecurrent):not(.sub-wrap):not(.read-more *):not(.anchor-hover *):not(#_x#_x#_x){background-color:#fffaf4!important}
body .cloud-label-widget-content a:not(#_x#_x#_x),body .label-head a:not(#_x#_x#_x),body a.read-more:not(#_x#_x#_x){background-color:#fffaf4!important}

/* === Ajustes v2 === */
.post-cmm{display:inline-flex!important;align-items:center!important;gap:7px!important;padding-left:6px!important}
.post-cmm .fa{margin-right:2px!important}
/* Tags: estado clicado/ativo/selecionado igual ao normal */
.label-size a,.label-size span,.label-size a:focus,.label-size a:active,.label-size a:visited,
.cloud-label-widget-content span,.list-label-widget-content span,.list-label-widget-content a:focus,
.Label a:focus,.Label a:active,.Label a:visited,.Label span{color:#6B2C2C!important;background:#fffaf4!important;border-color:#6B2C2C!important;opacity:1!important;outline:none!important;box-shadow:none!important}
.Label a:hover,.label-size a:hover{background:#6B2C2C!important;color:#F8F1E7!important}
/* Apenas 2 fontes */
body,p,li,a,span,input,textarea,button,code,pre,.post-body,.widget-content{font-family:'Lato',sans-serif}
h1,h2,h3,h4,h5,h6,.post-title,.widget h2,.title{font-family:'Playfair Display',Georgia,serif}
.fa{font-family:FontAwesome!important}

head.b:template-skin:
/*------Layout (No Edit)----------*/
body#layout #outer-wrapper {
    padding: 0;
    width: 800px
}
body#layout .section h4 {
    color: #333!important
}
body#layout #content-wrapper {
    margin: 0 auto
}

body#layout #main-wrapper {
    float: left;
    width: 70%;
    margin: 0;
    padding: 0
}

body#layout #sidebar-wrapper {
    float: right;
    width: 30%;
    margin: 0;
    padding: 5px 0 0;
    background-color: #f8e244!important;
display:block !important;
}
body#layout #sidebar-wrapper .section {
    background-color: #fffaf4;
    border: 1px solid #fff
}
body#layout #sidebar-wrapper .section .widget-content {
    border-color: #5a7ea2!important
}
body#layout #sidebar-wrapper .section .draggable-widget .widget-wrap2 {
    background-color: #5a7ea2!important
}

body#layout #main-wrapper #main {
    margin-right: 4px;
    background-color: #5a7ea2;
    border-color: #34495e
}
body#layout #main-wrapper #main h4 {
    color: #fff!important
}
body#layout .layout-widget-description {
    display: none!important
}
body#layout #Blog1 .widget-content {
    border-color: #34495e
}
/*------Layout (end)----------*/

